import React, { useMemo } from 'react';
import { View, Text, TouchableOpacity, ScrollView, Dimensions, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useTheme } from '../../context/ThemeContext';
import { useMuscleTracker, MuscleData } from '../../context/MuscleTrackerContext';
import { MUSCLE_IMAGES } from '../../constants/muscleImages';
import { Image } from 'react-native';

const { width } = Dimensions.get('window');

// Helper functions defined OUTSIDE component to avoid hoisting issues
const getPriorityScore = (status: string) => {
    switch (status) {
        case 'undertrained': return 10;
        case 'overreaching': return 8;
        case 'accumulating': return 5;
        case 'recovered': return 1;
        default: return 0;
    }
};

const getScoreColor = (score: number) => {
    if (score >= 80) return '#22C55E'; // Green
    if (score >= 50) return '#EAB308'; // Yellow
    return '#EF4444'; // Red
};

export function SmartCoach() {
    const { theme } = useTheme();
    const { muscleStats } = useMuscleTracker();

    // Sort muscles: 
    // 1. Undertrained (Yellow) first
    // 2. Overreaching (Red) second
    // 3. Accumulating (Blue)
    // 4. Recovered (Green)
    const sortedMuscles = useMemo(() => {
        if (!muscleStats) return [];
        return Object.values(muscleStats).sort((a, b) => {
            const scoreA = getPriorityScore(a.status);
            const scoreB = getPriorityScore(b.status);
            return scoreB - scoreA; // High priority first
        });
    }, [muscleStats]);

    const StatusBadge = ({ status }: { status: string }) => {
        let color = theme.colors.primary;
        let text = 'Neutro';
        let bg = 'bg-blue-500/10';

        switch (status) {
            case 'undertrained':
                color = '#EAB308'; // Yellow-500
                text = 'Subtreinado';
                bg = 'bg-yellow-500/20';
                break;
            case 'overreaching':
                color = '#EF4444'; // Red-500
                text = 'Sobrecarga';
                bg = 'bg-red-500/20';
                break;
            case 'recovered':
                color = '#22C55E'; // Green-500
                text = 'Volume Ideal';
                bg = 'bg-green-500/20';
                break;
            case 'accumulating':
                color = '#3B82F6'; // Blue-500
                text = 'Em Progresso';
                bg = 'bg-blue-500/20';
                break;
        }

        return (
            <View className={`px-2 py-1 rounded-md ${bg} self-start`}>
                <Text style={{ color }} className="text-[10px] font-bold uppercase">{text}</Text>
            </View>
        );
    };

    // Foco do Dia Logic within the new layout
    const dailyFocus = useMemo(() => {
        const undertrained = sortedMuscles.filter(m => m.status === 'undertrained').slice(0, 2);
        if (undertrained.length > 0) {
            return {
                title: "Foco sugerido hoje",
                names: undertrained.map(m => m.name).join(' + '),
                reason: "Volume semanal baixo",
                icon: "fitness"
            };
        }
        const overreaching = sortedMuscles.filter(m => m.status === 'overreaching').slice(0, 1);
        if (overreaching.length > 0) {
            return {
                title: "Descanso sugerido",
                names: overreaching[0].name,
                reason: "Sinais de sobrecarga",
                icon: "bed"
            };
        }
        return {
            title: "Tudo equilibrado",
            names: "Siga seu plano",
            reason: "Manutenção de volume",
            icon: "checkmark-done-circle"
        };
    }, [sortedMuscles]);

    return (
        <View className="mb-8">
            {/* Header Section */}
            <View className="px-6 mb-4 flex-row justify-between items-end">
                <View>
                    <Text style={{ color: theme.colors.textMuted }} className="text-xs uppercase tracking-widest font-bold mb-1">Coach Inteligente</Text>
                    <Text style={{ color: theme.colors.text }} className="text-xl font-bold">Objetivo do Acompanhamento</Text>
                </View>
            </View>

            {/* Daily Focus Banner */}
            <View className="px-6 mb-6">
                <View style={{ backgroundColor: theme.colors.card, borderColor: theme.colors.primary }} className="p-4 rounded-2xl border flex-row items-center shadow-sm">
                    <View className="bg-blue-100 dark:bg-blue-900/30 p-3 rounded-full mr-4">
                        <Ionicons name={dailyFocus.icon as any} size={24} color={theme.colors.primary} />
                    </View>
                    <View>
                        <Text style={{ color: theme.colors.textMuted }} className="text-xs font-bold uppercase">{dailyFocus.title}</Text>
                        <Text style={{ color: theme.colors.text }} className="text-lg font-bold">{dailyFocus.names}</Text>
                        <Text style={{ color: theme.colors.textSecondary }} className="text-xs mt-0.5">{dailyFocus.reason}</Text>
                    </View>
                </View>
            </View>

            {/* Horizontal Scroll Cards */}
            <ScrollView
                horizontal
                showsHorizontalScrollIndicator={false}
                contentContainerStyle={{ paddingHorizontal: 24, gap: 16 }}
            >
                {sortedMuscles.map((muscle) => (
                    <View
                        key={muscle.id}
                        style={{
                            backgroundColor: theme.colors.card,
                            borderColor: theme.colors.cardBorder,
                            width: 280, // Wider card for details
                            shadowColor: theme.colors.shadow,
                            shadowOffset: { width: 0, height: 4 },
                            shadowOpacity: 0.1,
                            shadowRadius: 8,
                            elevation: 4,
                            maxWidth: Platform.OS === 'web' ? 280 : undefined
                        }}
                        className="rounded-3xl p-5 border relative"
                    >
                        {/* Header: Name + Badge */}
                        <View className="flex-row justify-between items-start mb-4">
                            <View>
                                <Text style={{ color: theme.colors.text }} className="text-xl font-bold mb-1">{muscle.name}</Text>
                                <StatusBadge status={muscle.status} />
                            </View>
                            {/* Score Circle */}
                            <View className="items-center">
                                <Text style={{ color: getScoreColor(muscle.score) }} className="text-2xl font-black">{muscle.score}</Text>
                                <Text style={{ color: theme.colors.textMuted }} className="text-[10px] font-bold uppercase">Score</Text>
                            </View>
                        </View>

                        {/* Detailed Metrics Grid */}
                        <View className="flex-row flex-wrap gap-y-3 mb-5">
                            {/* Volume */}
                            <View className="w-[48%]">
                                <Text style={{ color: theme.colors.textMuted }} className="text-[10px] font-bold uppercase mb-0.5">Séries Semanais</Text>
                                <Text style={{ color: theme.colors.text }} className="text-sm font-bold">
                                    {muscle.setsThisWeek} <Text className="text-xs font-normal text-gray-400">/ {muscle.weeklyTarget}</Text>
                                </Text>
                            </View>
                            {/* Load */}
                            <View className="w-[48%]">
                                <Text style={{ color: theme.colors.textMuted }} className="text-[10px] font-bold uppercase mb-0.5">Carga Média</Text>
                                <Text style={{ color: theme.colors.text }} className="text-sm font-bold">{muscle.avgLoad}kg</Text>
                            </View>
                            {/* Frequency */}
                            <View className="w-[48%]">
                                <Text style={{ color: theme.colors.textMuted }} className="text-[10px] font-bold uppercase mb-0.5">Frequência</Text>
                                <Text style={{ color: theme.colors.text }} className="text-sm font-bold">{muscle.frequency}x / semana</Text>
                            </View>
                            {/* Recovery */}
                            <View className="w-[48%]">
                                <Text style={{ color: theme.colors.textMuted }} className="text-[10px] font-bold uppercase mb-0.5">Recuperação</Text>
                                <Text style={{ color: theme.colors.text }} className="text-sm font-bold">{muscle.recoveryPercentage}%</Text>
                            </View>
                        </View>

                        {/* Recommendation Box */}
                        {/* Recommendation Box */}
                        <View style={{ backgroundColor: theme.mode === 'light' ? '#F4F4F5' : '#18181B' }} className="p-4 rounded-xl mt-2">
                            <View className="flex-row items-center mb-1">
                                <Ionicons name="bulb" size={12} color={theme.colors.primary} style={{ marginRight: 6 }} />
                                <Text style={{ color: theme.colors.textMuted }} className="text-[10px] font-bold uppercase">Recomendação</Text>
                            </View>
                            <Text style={{ color: theme.colors.text }} className="text-xs font-semibold leading-5 italic">
                                "{muscle.recommendation}"
                            </Text>
                        </View>

                        {/* Decorative Background Image (Faded) */}
                        <View className="absolute bottom-0 right-0 opacity-5 pointer-events-none" style={{ width: 100, height: 100, overflow: 'hidden' }}>
                            {/* Placeholder or using muscleImages if available, keeping it simple for now */}
                            <Ionicons name="body" size={100} color={theme.colors.text} />
                        </View>
                    </View>
                ))}
            </ScrollView>
        </View>
    );
}
