import React, { useMemo } from 'react';
import { View, Text } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useTheme } from '../../context/ThemeContext';
import { WorkoutHistoryRecord } from '../../context/WorkoutHistoryContext';

interface Props {
    history: WorkoutHistoryRecord[];
}

export function WeeklyTimeline({ history }: Props) {
    const { theme } = useTheme();

    const weekData = useMemo(() => {
        const today = new Date();
        const day = today.getDay();
        const diff = today.getDate() - day + (day === 0 ? -6 : 1);
        const monday = new Date(today.setDate(diff));
        monday.setHours(0, 0, 0, 0);

        const days = [];
        const ptWeekdays = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];

        for (let i = 0; i < 7; i++) {
            const current = new Date(monday);
            // We must create a new date instance for calculation to avoid mutating 'monday' in loop logic if not careful
            // providing a fresh date object for each iteration
            current.setDate(monday.getDate() + i);

            const dateStr = current.toDateString();
            const workout = history.find(h => new Date(h.date).toDateString() === dateStr);

            const isToday = current.toDateString() === new Date().toDateString();
            const isFuture = current > new Date();

            let statusText = "Descanso";
            if (workout) {
                statusText = workout.workoutName || "Treino Realizado";
            } else if (isFuture) {
                statusText = "Planejado";
            }

            days.push({
                date: current,
                label: ptWeekdays[current.getDay()],
                dayNum: current.getDate(),
                workout,
                statusText,
                isToday,
                isFuture
            });
        }
        return days;
    }, [history]);

    return (
        <View className="mb-8 px-6">
            <Text style={{ color: theme.colors.textMuted }} className="text-xs uppercase tracking-widest font-bold mb-3">
                Linha do Tempo
            </Text>

            <View
                style={{
                    backgroundColor: theme.colors.card,
                    borderColor: theme.colors.cardBorder
                }}
                className="rounded-3xl border p-4"
            >
                {weekData.map((day, index) => (
                    <View key={index} className={`flex-row items-center py-3 ${index !== weekData.length - 1 ? 'border-b border-dashed' : ''}`} style={{ borderColor: theme.colors.border }}>

                        {/* Status Icon */}
                        <View
                            style={{
                                width: 32,
                                height: 32,
                                borderRadius: 12,
                                backgroundColor: day.workout
                                    ? (theme.mode === 'dark' ? '#10B98120' : '#DCFCE7')
                                    : (day.isToday ? theme.colors.primary + '20' : theme.colors.backgroundTertiary),
                                alignItems: 'center',
                                justifyContent: 'center',
                                marginRight: 12
                            }}
                        >
                            {day.workout ? (
                                <Ionicons name="checkmark" size={18} color="#10B981" />
                            ) : (
                                <Text style={{ color: day.isToday ? theme.colors.primary : theme.colors.textMuted, fontWeight: 'bold' }} className="text-xs">
                                    {day.dayNum}
                                </Text>
                            )}
                        </View>

                        {/* Text Details */}
                        <View className="flex-1">
                            <View className="flex-row items-center justify-between">
                                <Text
                                    style={{
                                        color: day.isToday ? theme.colors.primary : theme.colors.text,
                                        fontWeight: day.isToday ? 'bold' : '600'
                                    }}
                                    className="text-sm"
                                >
                                    {day.label}
                                </Text>
                                {day.isToday && (
                                    <View style={{ backgroundColor: theme.colors.primary + '20' }} className="px-2 py-0.5 rounded-md">
                                        <Text style={{ color: theme.colors.primary }} className="text-[10px] font-bold">HOJE</Text>
                                    </View>
                                )}
                            </View>

                            <Text
                                style={{
                                    color: day.workout ? theme.colors.text : theme.colors.textMuted,
                                    opacity: day.isFuture ? 0.5 : 1
                                }}
                                className="text-xs mt-0.5 capitalize"
                            >
                                {day.statusText}
                            </Text>
                        </View>
                    </View>
                ))}
            </View>
        </View>
    );
}
