import React, { useMemo } from 'react';
import { View, Text, TouchableOpacity, ScrollView } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useTheme } from '../../context/ThemeContext';
import { useMuscleTracker } from '../../context/MuscleTrackerContext';
import { LinearGradient } from 'expo-linear-gradient';

export function SmartRecovery() {
    const { theme } = useTheme();
    const { muscleStats } = useMuscleTracker();

    // Determine content based on muscle status
    const recoveryTip = useMemo(() => {
        if (!muscleStats) return null;

        // Find the most fatigued muscle (lowest recovery %) or recently trained
        const fatigued = Object.values(muscleStats)
            .sort((a, b) => a.recoveryPercentage - b.recoveryPercentage)[0];

        if (!fatigued) return {
            title: "Recuperação Ativa",
            mobility: "Faça uma caminhada leve de 20min para estimular a circulação.",
            nutrition: "Mantenha a hidratação constante ao longo do dia."
        };

        // Custom advice based on muscle group
        let mobilityTip = "Alongamento geral de corpo inteiro.";
        let nutritionTip = "Foque em proteínas magras para reconstrução muscular.";

        const lowerBody = ['Quadríceps', 'Isquiotibiais', 'Glúteos', 'Panturrilhas'];
        const upperPush = ['Peito', 'Ombros', 'Tríceps'];
        const upperPull = ['Costas', 'Bíceps', 'Trapézio'];

        if (lowerBody.includes(fatigued.name)) {
            mobilityTip = "Use o rolo de espuma (foam roller) nas pernas por 5 min.";
            nutritionTip = "Pernas exigem muito! Aumente carboidratos complexos hoje.";
        } else if (upperPush.includes(fatigued.name)) {
            mobilityTip = "Alongamento de peitoral na porta e rotação de ombros.";
            nutritionTip = "Vitamina C ajuda a reduzir o estresse oxidativo dos ombros.";
        } else if (upperPull.includes(fatigued.name)) {
            mobilityTip = "Pendure-se na barra fixa por 30s para descomprimir a coluna.";
            nutritionTip = "Magnésio antes de dormir relaxará a musculatura das costas.";
        }

        return {
            title: `Recuperação: ${fatigued.name}`,
            mobility: mobilityTip,
            nutrition: nutritionTip,
            muscle: fatigued.name
        };

    }, [muscleStats]);

    if (!recoveryTip) return null;

    return (
        <View className="mb-8 px-6">
            <View className="flex-row items-center justify-between mb-4">
                <View>
                    <Text style={{ color: theme.colors.textMuted }} className="text-xs uppercase tracking-widest font-bold mb-1">
                        Premium
                    </Text>
                    <Text style={{ color: theme.colors.text }} className="text-xl font-bold">
                        Smart Recovery
                    </Text>
                </View>
                <View style={{ backgroundColor: '#8B5CF620' }} className="px-3 py-1 rounded-full">
                    <Text style={{ color: '#8B5CF6' }} className="text-xs font-bold">AI BETA</Text>
                </View>
            </View>

            <LinearGradient
                colors={theme.mode === 'dark' ? ['#1F2937', '#111827'] : ['#F3F4F6', '#FFFFFF']}
                style={{
                    borderRadius: 24,
                    padding: 2, // Border width mimic
                    shadowColor: theme.colors.shadow,
                    shadowOffset: { width: 0, height: 4 },
                    shadowOpacity: 0.1,
                    shadowRadius: 10,
                    elevation: 5
                }}
            >
                <View style={{ backgroundColor: theme.colors.card, borderRadius: 22 }} className="overflow-hidden">
                    {/* Glass Header Effect */}
                    <View className="p-5 border-b" style={{ borderColor: theme.colors.border }}>
                        <View className="flex-row items-center mb-2">
                            <Ionicons name="medical" size={20} color="#EF4444" style={{ marginRight: 8 }} />
                            <Text style={{ color: theme.colors.text }} className="font-bold text-lg">
                                Foco: {recoveryTip.muscle || "Geral"}
                            </Text>
                        </View>
                        <Text style={{ color: theme.colors.textMuted }} className="text-sm">
                            Baseado na intensidade do seu último treino.
                        </Text>
                    </View>

                    <View className="p-5 flex-row">
                        {/* Mobility Column */}
                        <View className="flex-1 mr-4">
                            <View className="flex-row items-center mb-2">
                                <View className="w-8 h-8 rounded-full bg-blue-500/10 items-center justify-center mr-2">
                                    <Ionicons name="body" size={16} color="#3B82F6" />
                                </View>
                                <Text style={{ color: theme.colors.text }} className="font-bold text-sm">Mobilidade</Text>
                            </View>
                            <Text style={{ color: theme.colors.textMuted }} className="text-xs leading-5">
                                {recoveryTip.mobility}
                            </Text>
                        </View>

                        {/* Divider */}
                        <View style={{ width: 1, backgroundColor: theme.colors.border }} />

                        {/* Nutrition Column */}
                        <View className="flex-1 ml-4">
                            <View className="flex-row items-center mb-2">
                                <View className="w-8 h-8 rounded-full bg-green-500/10 items-center justify-center mr-2">
                                    <Ionicons name="nutrition" size={16} color="#10B981" />
                                </View>
                                <Text style={{ color: theme.colors.text }} className="font-bold text-sm">Nutrição</Text>
                            </View>
                            <Text style={{ color: theme.colors.textMuted }} className="text-xs leading-5">
                                {recoveryTip.nutrition}
                            </Text>
                        </View>
                    </View>
                </View>
            </LinearGradient>
        </View>
    );
}
