import React from 'react';
import { View, Text, Modal, TouchableOpacity, ScrollView, Dimensions, Platform } from 'react-native';
import { Ionicons } from '@expo/vector-icons';
import { useTheme } from '../context/ThemeContext';
import { useNotifications, Notification, NotificationType } from '../context/NotificationContext';
import { BlurView } from 'expo-blur';

const { height: SCREEN_HEIGHT } = Dimensions.get('window');

interface NotificationModalProps {
    visible: boolean;
    onClose: () => void;
}

const getIconForType = (type: NotificationType) => {
    switch (type) {
        case 'achievement': return { name: 'trophy', color: '#FFD700' };
        case 'recovery': return { name: 'fitness', color: '#10B981' };
        case 'consistency': return { name: 'flame', color: '#FF9500' };
        case 'pr': return { name: 'barbell', color: '#4F8FF7' };
        default: return { name: 'information-circle', color: '#6366F1' };
    }
};

const formatDate = (timestamp: number) => {
    const date = new Date(timestamp);
    const now = new Date();
    const diff = now.getTime() - date.getTime();

    if (diff < 3600000) return 'Agora mesmo';
    if (diff < 86400000) return `${Math.floor(diff / 3600000)}h atrás`;
    return date.toLocaleDateString('pt-BR', { day: '2-digit', month: 'short' });
};

export const NotificationModal = ({ visible, onClose }: NotificationModalProps) => {
    const { theme } = useTheme();
    const { notifications, markAsRead, markAllAsRead, deleteNotification, clearAll } = useNotifications();

    const Content = () => (
        <View
            style={{
                backgroundColor: theme.colors.background,
                borderTopLeftRadius: 32,
                borderTopRightRadius: 32,
                height: SCREEN_HEIGHT * 0.85,
                marginTop: SCREEN_HEIGHT * 0.15,
                shadowColor: '#000',
                shadowOffset: { width: 0, height: -4 },
                shadowOpacity: 0.2,
                shadowRadius: 12,
                elevation: 20
            }}
            className="flex-1"
        >
            {/* Header */}
            <View className="px-6 py-5 flex-row items-center justify-between border-b" style={{ borderColor: theme.colors.border }}>
                <View className="flex-row items-center">
                    <Text style={{ color: theme.colors.text }} className="text-2xl font-extrabold italic tracking-tighter mr-2">
                        NOTIFICAÇÕES
                    </Text>
                    {notifications.filter(n => !n.isRead).length > 0 && (
                        <View className="bg-primary px-2 py-0.5 rounded-full">
                            <Text className="text-white text-[10px] font-bold">
                                {notifications.filter(n => !n.isRead).length}
                            </Text>
                        </View>
                    )}
                </View>

                <TouchableOpacity onPress={onClose} className="p-2 bg-zinc-800/10 rounded-full">
                    <Ionicons name="close" size={24} color={theme.colors.text} />
                </TouchableOpacity>
            </View>

            <ScrollView
                className="flex-1"
                contentContainerStyle={{ padding: 20, paddingBottom: 40 }}
                showsVerticalScrollIndicator={false}
            >
                {notifications.length === 0 ? (
                    <View className="flex-1 items-center justify-center py-20">
                        <View className="w-20 h-20 bg-zinc-800/5 rounded-full items-center justify-center mb-4">
                            <Ionicons name="notifications-off-outline" size={40} color={theme.colors.textMuted} />
                        </View>
                        <Text style={{ color: theme.colors.text }} className="text-lg font-bold">Tudo limpo por aqui!</Text>
                        <Text style={{ color: theme.colors.textMuted }} className="text-center mt-2 px-10">
                            Você não tem novas notificações no momento. Continue treinando para ver aqui suas conquistas!
                        </Text>
                    </View>
                ) : (
                    <>
                        {/* Actions Row */}
                        <View className="flex-row justify-end mb-6">
                            <TouchableOpacity onPress={markAllAsRead} className="mr-4">
                                <Text style={{ color: theme.colors.primary }} className="text-xs font-bold uppercase tracking-wider">MARCAR TUDO COMO LIDO</Text>
                            </TouchableOpacity>
                            <TouchableOpacity onPress={clearAll}>
                                <Text style={{ color: theme.colors.textMuted }} className="text-xs font-bold uppercase tracking-wider">LIMPAR TUDO</Text>
                            </TouchableOpacity>
                        </View>

                        {notifications.map((notif) => {
                            const icon = getIconForType(notif.type);
                            return (
                                <TouchableOpacity
                                    key={notif.id}
                                    onPress={() => markAsRead(notif.id)}
                                    activeOpacity={0.7}
                                    style={{
                                        backgroundColor: notif.isRead ? 'transparent' : `${theme.colors.primary}08`,
                                        borderColor: notif.isRead ? theme.colors.border : theme.colors.primary,
                                        borderLeftWidth: notif.isRead ? 0 : 4
                                    }}
                                    className="mb-4 p-4 rounded-2xl flex-row items-start border"
                                >
                                    <View
                                        style={{ backgroundColor: `${icon.color}15` }}
                                        className="w-12 h-12 rounded-xl items-center justify-center mr-4"
                                    >
                                        <Ionicons name={icon.name as any} size={24} color={icon.color} />
                                    </View>

                                    <View className="flex-1">
                                        <View className="flex-row items-center justify-between mb-1">
                                            <Text
                                                style={{ color: theme.colors.text }}
                                                className={`text-base flex-1 mr-2 ${notif.isRead ? 'font-semibold' : 'font-bold'}`}
                                            >
                                                {notif.title}
                                            </Text>
                                            <Text style={{ color: theme.colors.textMuted }} className="text-[10px]">
                                                {formatDate(notif.timestamp)}
                                            </Text>
                                        </View>

                                        <Text style={{ color: theme.colors.textSecondary }} className="text-sm leading-5">
                                            {notif.message}
                                        </Text>

                                        {!notif.isRead && (
                                            <View className="mt-3 flex-row items-center">
                                                <View className="w-2 h-2 rounded-full bg-primary mr-2" />
                                                <Text style={{ color: theme.colors.primary }} className="text-[10px] font-bold uppercase tracking-tighter">Novo</Text>
                                            </View>
                                        )}
                                    </View>

                                    <TouchableOpacity
                                        onPress={() => deleteNotification(notif.id)}
                                        className="ml-2 p-1"
                                    >
                                        <Ionicons name="trash-outline" size={16} color={theme.colors.textMuted} />
                                    </TouchableOpacity>
                                </TouchableOpacity>
                            );
                        })}
                    </>
                )}
            </ScrollView>
        </View>
    );

    return (
        <Modal
            visible={visible}
            animationType="slide"
            transparent={true}
            onRequestClose={onClose}
        >
            {Platform.OS !== 'web' ? (
                <BlurView intensity={20} tint={theme.mode === 'dark' ? 'dark' : 'light'} className="flex-1">
                    <Content />
                </BlurView>
            ) : (
                <View style={{ flex: 1, backgroundColor: 'rgba(0,0,0,0.5)' }}>
                    <Content />
                </View>
            )}
        </Modal>
    );
};
